def min_cost_to_illuminate_street(n, m, k, blocked_positions, lamp_costs):
    blocked = [False] * n
    for pos in blocked_positions:
        blocked[pos] = True

    def can_cover(power):
        covered = set()
        i = 0
        while i < n:
            if blocked[i]:
                i += 1
            else:
                start = max(0, i - power)
                end = min(n, i + power + 1)
                covered.update(range(start, end))
                i = end
        return len(covered) == n

    min_cost = float('inf')
    for power in range(1, k + 1):
        if can_cover(power):
            min_cost = min(min_cost, lamp_costs[power - 1])

    return min_cost if min_cost != float('inf') else -1

