def min_cost_to_illuminate_street(n, m, k, blocked_positions, lamp_costs):
    blocked_set = set(blocked_positions)
    covered = [False] * n

    for i in range(n):
        if i in blocked_set:
            continue
        for j in range(k):
            power = j + 1
            if i + power >= n or covered[i + power]:
                continue
            if i + power - 1 > n - 1:
                break
            covered[i:i+power+1] = [True] * (power + 1)

    if all(covered):
        return min(lamp_costs[:k])
    else:
        return -1

