def min_cost_to_illuminate(n, m, k, blocked_positions, lamp_costs):
    blocked = set(blocked_positions)
    dp = [-1] * (n + 1)

    # Initialize DP array with infinity except for dp[0]
    for i in range(1, n + 1):
        dp[i] = float('inf')

    # Iterate over all possible lamp powers
    for power in range(1, k + 1):
        cost = lamp_costs[power - 1]
        for i in range(power, n + 1):
            if i not in blocked:
                if i == power:
                    dp[i] = min(dp[i], cost)
                else:
                    dp[i] = min(dp[i], dp[i - power] + cost)

    return dp[n]

