from typing import List

def min_cost_to_illuminate(n: int, m: int, k: int, blocked_positions: List[int], lamp_costs: List[int]) -> int:
    blocked_set = set(blocked_positions)
    if 0 in blocked_set or n - 1 in blocked_set:
        return -1

    def can_illuminate(power: int) -> bool:
        i = 0
        while i < n:
            if i in blocked_set:
                i += 1
                continue
            end = min(i + power, n)
            while end > i and end in blocked_set:
                end -= 1
            if end == i:
                return False
            i = end + 1
        return True

    for power in range(1, k + 1):
        if can_illuminate(power):
            return lamp_costs[power - 1]

    return -1

